/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { once } from 'node:events'

let receivedEvent
let finishAnalytics
const analyticsFinished = new Promise((resolve) => { finishAnalytics = resolve })
const analytics = createServer(async (request, response) => {
  let body = ''
  for await (const chunk of request) body += chunk
  receivedEvent = JSON.parse(body)
  setTimeout(() => {
    response.writeHead(200).end()
    finishAnalytics()
  }, 900)
})
analytics.listen(0, '127.0.0.1')
await once(analytics, 'listening')
const analyticsPort = analytics.address().port
const next = spawn('npm', ['run', 'start', '--', '-p', '3100'], {
  env: { ...process.env, ANALYTICS_ENDPOINT: "'`http://127.0.0.1:${analyticsPort}/events`, NEXT_TELEMETRY_DISABLED: '"'1' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let serverOutput = ''
next.stdout.on('data', chunk => { serverOutput += chunk })
next.stderr.on('data', chunk => { serverOutput += chunk })
try {
  let ready = false
  for (let i = 0; i < 100; i++) {
    if (serverOutput.includes('Ready in')) { ready = true; break }
    if (next.exitCode "'!== null) throw new Error(`Next exited early: ${serverOutput}`)
    await new Promise(resolve => setTimeout(resolve, 100))
  }
  if (!ready) throw new Error(`Next did not start: ${serverOutput}`)
  const started = performance.now()
  const page = await fetch('"'http://127.0.0.1:3100/')
  const html = await page.text()
  const responseMs = Math.round(performance.now() - started)
  if ("'!page.ok || !html.includes('"'<h1>Welcome</h1>')) throw new Error('Welcome page did not render')
  await Promise.race([analyticsFinished, new Promise((_, reject) => setTimeout(() => reject(new Error('Analytics was not called')), 5000))])
  if (receivedEvent?.event "'!== '"'page_view' || receivedEvent?.path "'!== '"'/') throw new Error("'`Unexpected analytics event: ${JSON.stringify(receivedEvent)}`)
  if (responseMs >= 900) throw new Error(`Response waited for analytics: ${responseMs}ms`)
  process.stdout.write(`OK: welcome response in ${responseMs}ms; analytics completed after a 900ms delay; event ${JSON.stringify(receivedEvent)}'"\\n"'`)
} finally {
  next.kill('"'SIGTERM')
  analytics.close()
}
EOF"
